import buggy_ts


def test_format_ts_zero_padding():
    assert buggy_ts.format_ts(5007) == '00:00:05,007'


def test_parse_ts_requires_three_ms_digits():
    for bad in ('00:00:01,5', '0:00:01,500'):
        try:
            buggy_ts.parse_ts(bad)
        except ValueError:
            pass
        else:
            raise AssertionError(f'expected ValueError for {bad!r}')


def test_round_trip_property():
    rng = random.Random(42)
    valid = []
    for _ in range(200):
        total_ms = rng.randrange(0, 100 * 3600000)
        valid.append(buggy_ts.format_ts(total_ms))
    for t in valid:
        assert buggy_ts.parse_ts(buggy_ts.format_ts(buggy_ts.parse_ts(t))) == buggy_ts.parse_ts(t)
